<?php namespace Webzine\Cartographic; ?>
<?php if(get_post_type()==='fa_place'): $id=get_the_ID(); ?>
<dl class="ca-record"><dt><?php esc_html_e('地址','webzine-cartographic'); ?></dt><dd><?php echo esc_html(get_post_meta($id,'_fa_address',true) ?: __('未填写','webzine-cartographic')); ?></dd><dt><?php esc_html_e('坐标','webzine-cartographic'); ?></dt><dd><?php $lat=get_post_meta($id,'_fa_lat',true);$lon=get_post_meta($id,'_fa_lon',true);echo is_numeric($lat)&&is_numeric($lon)?esc_html($lat.', '.$lon):esc_html__('未填写','webzine-cartographic'); ?></dd><dt><?php esc_html_e('坐标说明','webzine-cartographic'); ?></dt><dd><?php echo esc_html(get_post_meta($id,'_fa_coordinate_note',true)); ?></dd><dt><?php esc_html_e('公开编辑备注','webzine-cartographic'); ?></dt><dd><?php echo esc_html(get_post_meta($id,'_fa_notes',true)); ?></dd><dt><?php esc_html_e('核查记录','webzine-cartographic'); ?></dt><dd><?php echo esc_html(get_post_meta($id,'_fa_verified',true) ?: __('尚未核验','webzine-cartographic')); ?></dd>
<?php foreach(array('website'=>__('官方网站','webzine-cartographic'),'source'=>__('资料来源','webzine-cartographic')) as $key=>$label): $url=esc_url(get_post_meta($id,'_fa_'.$key,true));if(!$url)continue; ?><dt><?php echo esc_html($label); ?></dt><dd><a href="<?php echo esc_url($url); ?>" rel="noopener noreferrer"><?php echo esc_html($label); ?> ↗</a></dd><?php endforeach; ?></dl>
<?php $images=array_values(array_filter(array_map('absint',explode(',',get_post_meta($id,'_fa_gallery_ids',true))),static fn($image)=>get_post_type($image)==='attachment'));if($images): ?><section><h2><?php esc_html_e('地点图像','webzine-cartographic'); ?></h2><?php echo do_shortcode('[gallery ids="'.implode(',',$images).'" link="file" columns="3"]'); ?></section><?php endif; ?>
<?php elseif(get_post_type()==='fa_route'): ?><div class="ca-route-stops"><h2><?php esc_html_e('路线中的地点','webzine-cartographic'); ?></h2><ol><?php foreach(array_filter(array_map('absint',explode(',',get_post_meta(get_the_ID(),'_fa_stop_ids',true)))) as $id): if(get_post_type($id)!=='fa_place'||get_post_status($id)!=='publish'||post_password_required($id))continue; ?><li><a href="<?php echo esc_url(get_permalink($id)); ?>"><?php echo esc_html(get_the_title($id)); ?></a></li><?php endforeach; ?></ol><p class="wz-muted"><?php echo esc_html(get_post_meta(get_the_ID(),'_fa_geometry_status',true)==='calculated'?__('已计算轨迹，仍须独立确认实际通行条件。','webzine-cartographic'):__('编辑示意路线，未经路网与实际通行核验。','webzine-cartographic')); ?></p></div>
<?php elseif(get_post_type()==='fa_collection'): ?><section><h2><?php esc_html_e('清单中的地点','webzine-cartographic'); ?></h2><ul><?php foreach(array_filter(array_map('absint',explode(',',get_post_meta(get_the_ID(),'_fa_place_ids',true)))) as $id): if(get_post_type($id)!=='fa_place'||get_post_status($id)!=='publish'||post_password_required($id))continue; ?><li><a href="<?php echo esc_url(get_permalink($id)); ?>"><?php echo esc_html(get_the_title($id)); ?></a></li><?php endforeach; ?></ul></section><?php endif; ?>
